export function svg(name) { return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${['globe','clock','info'].includes(name)?'<circle cx="12" cy="12" r="9"/>':''}${name==='search'?'<circle cx="10" cy="10" r="6"/>':''}${name==='key'?'<circle cx="16" cy="6" r="4"/>':''}${name==='theme'?'<circle cx="12" cy="12" r="4"/>':''}<path d="${paths[name]||paths.grid}"/>${name==='settings'?'<circle cx="12" cy="12" r="3"/>':''}</svg>`; }
const make = (tag, cls, text) => {const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const button = (text, onClick, icon) => {const b=make('button','ns-button');b.type='button';if(icon)b.innerHTML=svg(icon);b.append(document.createTextNode(text));b.onclick=onClick;return b;};
const uid = () => crypto.randomUUID();
function appendDiffLines(pre,source,addedOnly=false){
  let oldLine=0,newLine=addedOnly?1:0;
  for(const line of source){
    const hunk=/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(line);
    if(hunk){oldLine=Number(hunk[1]);newLine=Number(hunk[2]);pre.append(make('div','ns-diff-hunk',line));continue;}
    if(!addedOnly&&/^(diff --git|index |--- |\+\+\+ )/.test(line))continue;
    const added=addedOnly||line.startsWith('+'),removed=!addedOnly&&line.startsWith('-');
    const row=make('div','ns-diff-line '+(added?'added':removed?'removed':''));
    const number=make('span','ns-line-number',String(removed?oldLine||'':newLine||''));number.setAttribute('aria-hidden','true');
    row.append(number,make('span','ns-line-source',addedOnly?'+'+line:line||' '));pre.append(row);
    if(!added)oldLine++;if(!removed)newLine++;
  }
}


/** هل صدى المحرّك (`settings`) يؤكّد الرقعةَ المرسلة؟ مالكُ هذا السؤال الواحد — مقيسٌ 2026-09-13 عبر CDP على
 * التطبيق المثبَّت: المحرّك يحذف `visionModel` الفارغ عند الحفظ (`saveSettings`) فيعود الصدى بلا الحقل، بينما
 * الرقعةُ تحمل `""` — فكانت المطابقةُ الحرفيّة ترفض نجاحاً حقيقيّاً، وتنتظر ١٥ ثانية، ثمّ تعلن «لم يؤكّد المحرّك»
 * — واللغةُ لا تتغيّر أبداً، واللوحةُ مقفلةٌ (inert) طوال الانتظار. القاعدة: «فارغٌ مطلوب» يساوي «غائبٌ أو فارغٌ مقبول». */
export function settingsPatchConfirmed(actual, wanted) {
  if (wanted && typeof wanted === 'object') return Object.entries(wanted).every(([k, v]) => settingsPatchConfirmed(actual?.[k], v));
  if (wanted === '') return actual === undefined || actual === null || actual === '';
  return actual === wanted;
}

