  const filterTools=make('div','ns-session-tools');const filter=make('input','ns-session-search');filter.placeholder='Search conversations';filter.type='search';filter.oninput=renderSessions;const sessionOptions=button('',e=>menu(e.currentTarget,[[L('All conversations','كل المحادثات'),()=>{sessionView='all';renderSessions();}],[L('Ready','جاهزة'),()=>{sessionView='ready';renderSessions();}],[L('Needs input','تحتاج تدخلاً'),()=>{sessionView='needs-input';renderSessions();}],[L('Completed','مكتملة'),()=>{sessionView='done';renderSessions();}],[L('Sort: recent','الترتيب: الأحدث'),()=>{sessionSort='recent';renderSessions();}],[L('Sort: title','الترتيب: العنوان'),()=>{sessionSort='title';renderSessions();}]]),'settings');sessionOptions.title='Filter and sort conversations';filterTools.append(filter,sessionOptions);aside.insertBefore(filterTools,$('sessions'));
