  let scheduled=false;
  function reconcile(){
    scheduled=false;
    const labels={terminal:L('Terminal','الطرفية'),tasks:L('Tasks','المهام'),servers:L('Servers','الخوادم'),trajectory:L('Trajectory','المسار'),deliverables:L('Deliverables','المخرجات'),approvals:L('Approvals','الموافقات')};
    const present=new Set();
    for(const node of document.querySelectorAll('[data-slot^="panel:"]')){
      const slot=node.dataset.slot,id=slot.slice('panel:'.length);
      if(!/^[a-z-]{1,32}$/.test(id))continue;
      present.add(id);const known=dock.nodes.get(id);
      if(!known||known.node!==node){dock.register(id,node,{title:labels[id]||node.getAttribute('aria-label')||id.replaceAll('-',' '),slotId:slot,close:()=>bridge.closePanel(id)});if(id==='terminal')renderTerminalOutput();}
    }
    for(const [id,item] of [...dock.nodes])if(item.slotId?.startsWith('panel:')&&!present.has(id))dock.detach(id);
    const browser=$('pane')||dock.nodes.get('browser')?.node;
    if(browser){const visible=document.body.classList.contains('paneopen');if(visible&&!dock.nodes.has('browser'))dock.register('browser',browser,{title:L('Browser','المتصفّح'),close:()=>bridge.closeBrowser()});else if(!visible&&dock.nodes.has('browser')){dock.detach('browser');staging.append(browser);}}
    if(settings.classList.contains('open'))bridge.park();
  }
