  reconcile();renderNavigation();renderWelcome();applyLocale('en');setStage('idle');fillSuper();
  native.api={bridge,native,dock,pageHost,producedFiles,rootProject,showPage,renderPage,settingsTab,formDialog,confirmDialog,menu,reportError:error,saveStore:safeSave,applyWorkspacePreferences,openProject,addProject,projectDialog,openFiles:files,openChanges:changes,openPreview:openFile,applyRuntimeSettings,L,button,make,svg,setShellMode:native.setShellMode,get state(){return {metadata,page,lang,shellMode,sessions};}};
